```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_VEHICLES 10
#define MAX_LENGTH 50

void printVehicle(char* vehicles[], int index) {
    if (index >= 0 && index < MAX_VEHICLES) {
        printf("The vehicle at index %d is: %s\n", index, vehicles[index]);
    } else {
        printf("Invalid index!\n");
    }
}

int main() {
    char* vehicles[MAX_VEHICLES];
    int i;

    // Initialize the array of strings
    for (i = 0; i < MAX_VEHICLES; i++) {
        vehicles[i] = (char*)malloc(MAX_LENGTH * sizeof(char));
        if (vehicles[i] == NULL) {
            fprintf(stderr, "Memory allocation failed!\n");
            return EXIT_FAILURE;
        }
    }

    // Populate the array with some example vehicle names
    strcpy(vehicles[0], "Car");
    strcpy(vehicles[1], "Bike");
    strcpy(vehicles[2], "Truck");
    strcpy(vehicles[3], "Motorcycle");
    strcpy(vehicles[4], "Sedan");
    strcpy(vehicles[5], "SUV");
    strcpy(vehicles[6], "Van");
    strcpy(vehicles[7], "Bus");
    strcpy(vehicles[8], "Tractor");
    strcpy(vehicles[9], "Bicycle");

    // Prompt the user for the index of a vehicle
    int index;
    printf("Enter the index of a vehicle (0-%d): ", MAX_VEHICLES - 1);
    scanf("%d", &index);

    // Print out the selected vehicle
    printVehicle(vehicles, index);

    // Print out all vehicles in the array
    printf("\nAll vehicles:\n");
    for (i = 0; i < MAX_VEHICLES; i++) {
        if (strlen(vehicles[i]) > 0) {
            printf("Index %d: %s\n", i, vehicles[i]);
        }
    }

    // Free the allocated memory
    for (i = 0; i < MAX_VEHICLES; i++) {
        free(vehicles[i]);
    }

    return EXIT_SUCCESS;
}
```

### Explanation:
1. **Array Initialization**: The `vehicles` array is initialized with pointers to strings, and each pointer is dynamically allocated to hold up to `MAX_LENGTH` characters.
2. **Populating the Array**: Example vehicle names are stored in the array using the `strcpy` function.
3. **User Input**: The user is prompted to enter an index. The program checks if the index is within the valid range and prints the corresponding vehicle name.
4. **Looping Through the Array**: The program loops through the entire array and prints out each vehicle that has a non-empty string (i.e., it has been assigned a value).
5. **Memory Management**: Dynamic memory allocated for each string is freed before the program exits to avoid memory leaks.

This code ensures that the user can interact with an array of strings, retrieve specific elements based on user input, and print all elements in the array.']

