#include <stdio.h>
#include <stdlib.h>

// Function to create and print the format string with variable arguments
char* print(const char* format, ...) {
    va_list args;
    va_start(args, format);

    // Determine the length of the formatted string
    int len = vsnprintf(NULL, 0, format, args);
    va_end(args);

    if (len <= 0) {
        return NULL; // Handle error in snprintf
    }

    // Allocate memory for the formatted string
    char* str = malloc(len + 1);
    if (str == NULL) {
        return NULL; // Handle memory allocation failure
    }

    // Format the string and store it in allocated memory
    va_list args2;
    va_start(args2, format);
    vsnprintf(str, len + 1, format, args2);
    va_end(args2);

    return str;
}

// Function to execute a command with a dynamically created argument string
void execute_command(const char* command, ...) {
    va_list args;
    va_start(args, command);

    // Create the argument string using print function
    char* arg_str = print(command, args);
    if (arg_str == NULL) {
        fprintf(stderr, "Error creating argument string\n");
        va_end(args);
        return;
    }

    // Execute the command with the argument string
    char full_command[1024];
    snprintf(full_command, sizeof(full_command), "%s %s", "ls", arg_str);

    FILE* pipe = popen(full_command, "r");
    if (!pipe) {
        fprintf(stderr, "Failed to run command\n");
        free(arg_str);
        va_end(args);
        return;
    }

    // Read the output from the command
    char buffer[128];
    while (fgets(buffer, sizeof(buffer), pipe) != NULL) {
        printf("%s", buffer);
    }

    // Close the pipe and free allocated memory
    pclose(pipe);
    free(arg_str);
    va_end(args);
}

int main() {
    // Example usage of execute_command function
    const char* arg_format = "-l %s";
    execute_command(arg_format, "directory");
    return 0;
}
```

